<?php
namespace FurMedia\Cache;
class ExternalAssets {
 public static function import($url,$hash,$type,$root,$fetch=null,array $options=array()){if(!is_string($url)||!is_string($hash)||!is_string($type)||!in_array($type,array('css','js'),true)||!preg_match('/^[a-f0-9]{64}$/D',$hash)||!preg_match('~^https://[a-z0-9.-]+/[^\s]*$~iD',$url)||preg_match('/[\r\n]/',$url)){throw new \InvalidArgumentException('Import requires public HTTPS URL, css/js and expected SHA256');}Delivery::urls($url);$result=$fetch?call_user_func($fetch,$url):(new HttpClient())->get($url,2097152,10);$body=$result['body'];if(!is_string($body)||strlen($body)>2097152||!hash_equals($hash,hash('sha256',$body))){throw new \RuntimeException('Import hash or size mismatch');}if($type==='css'){if(preg_match('/@import\b/i',$body)){throw new \InvalidArgumentException('Resolve CSS imports before pinning local CSS');}$origin=parse_url($url,PHP_URL_SCHEME).'://'.parse_url($url,PHP_URL_HOST);$path=parse_url($url,PHP_URL_PATH);$base=$origin.substr($path,0,strrpos($path,'/')+1);$body=preg_replace_callback('~url\(\s*([\x22\x27]?)(.*?)\1\s*\)~i',function($m)use($base,$origin){$v=$m[2];if($v===''){return $m[0];}if(preg_match('~^(?:[a-z]+:|//|\#)~i',$v)){return $m[0];}return 'url("'.($v[0]==='/'?$origin.$v:$base.$v).'")';},$body);}$targetHash=hash('sha256',$body);if(!is_dir($root)&&!mkdir($root,0755,true)){throw new \RuntimeException('Asset directory unavailable');}if(is_link($root)){throw new \RuntimeException('Symlink assets refused');}if(!is_file($root.'/.htaccess')){file_put_contents($root.'/.htaccess',"Options -Indexes\n<IfModule mod_headers.c>\n<FilesMatch \"^[a-f0-9]{64}\\.(css|js|webp|avif)$\">\nHeader set Cache-Control \"public, max-age=31536000, immutable\"\nHeader set X-Content-Type-Options \"nosniff\"\n</FilesMatch>\n</IfModule>\n<FilesMatch \"^(import-|minify-|convert-|\\.)\">\nRequire all denied\n</FilesMatch>\n");}$options=array_merge(Settings::defaults(),$options);$lock=fopen($root.'/.lock','c');if(!$lock||!flock($lock,LOCK_EX|LOCK_NB)){if($lock){fclose($lock);}throw new \RuntimeException('Asset writer busy');}try{$target=$root.'/'.$targetHash.'.'.$type;if(is_link($target)){throw new \RuntimeException('Symlink target refused');}$bytes=0;foreach(glob($root.'/*')?:array() as $file){if(is_file($file)){$bytes+=filesize($file);}}$free=disk_free_space($root);if((!is_file($target)&&$bytes+strlen($body)>$options['max_mb']*1048576)||($free!==false&&$free<$options['reserve_mb']*1048576+strlen($body))){throw new \RuntimeException('Asset quota or disk reserve reached');}$tmp=tempnam($root,'import-');if(file_put_contents($tmp,$body,LOCK_EX)!==strlen($body)||!rename($tmp,$target)){if(is_file($tmp)){unlink($tmp);}throw new \RuntimeException('Atomic import failed');}return array('file'=>$targetHash.'.'.$type,'source_hash'=>$hash,'stored_hash'=>$targetHash,'bytes'=>strlen($body));}finally{flock($lock,LOCK_UN);fclose($lock);}}
}
